// Purpose: ROW-024 (REQ-012) — on the checker page, in every browser of the harness, Ignore removes
// the highlight of that one occurrence only, lowers the count by one, leaves the text unchanged, and
// the word is flagged again on the next check.
// Provenance: generated by tests/invariants/spanish-dictionary.ts (accentPopulation, dictionary-es
// 4.0.0 pinned by SHA-256) with a fresh seed per run; positions are the test's own record.
//
// Test argument
// ROW-024 promise: Ignore removes the highlight of only that occurrence, for the current check only,
//   lowers the count by one, does not change the text, and the next check flags the word again
//   (REQ-012 fail-if: Ignore changes the text, removes another occurrence's highlight, leaves the
//   count unchanged, or the ignored word is not flagged again; A-018; NG-003 nothing remembered).
// ROW-024 wrong product: an Ignore that removes every highlight of the same word (ignore-all), or
//   that keeps an "ignored words" set for the page's life (or in storage) so the next check skips
//   the word, or that leaves the count at its old number.
// ROW-024 given: a fresh misspelling s written twice and a second fresh misspelling t; when: the first
//   s's menu is opened and Ignore is chosen, then Revisar ortografía is pressed again; then: after
//   Ignore the text is exactly as entered, the highlights are exactly the second s and t at their
//   places and the count's number is one less; after the new check both s and t are highlighted again
//   — and before Ignore all three were highlighted.
// ROW-024 controls: the first check highlights both occurrences of s and t and the first s's menu shows
//   Ignore — the path is reached; untouched by any Ignore fault.
// ROW-024 technique: a repeat as the near miss (same word, one ignored), whole-list comparisons,
//   before/after on the same objects, fresh words per run.
// cases: ROW-024 target=ROW-024-ignore-clears-only-that-occurrence-lowers-the-count-and-the-word-returns-on-the-next-check control=ROW-024-control-both-occurrences-are-highlighted-and-the-menu-offers-ignore

import { expect, test, type Page } from '@playwright/test';
import { accentPopulation, asActor, compose, enterOffer, freshRandom, openChecker, pressCheck, readHighlights, type Rng } from './harness';
import { chooseIgnore, openMenuByPointer, readCount, readOfferText } from './suggestions-helpers';

const WAIT_MS = 15_000;

function offer(rng: Rng) {
  const pop = accentPopulation();
  const a = rng.pick(pop);
  let b = rng.pick(pop);
  while (b.word === a.word || b.stripped.includes(a.stripped) || a.stripped.includes(b.stripped)) b = rng.pick(pop);
  const { text, placed } = compose(['buscamos', a.stripped, 'para', 'el', 'equipo', 'con', b.stripped, 'y', 'otra', a.stripped, 'en', 'la', 'oficina']);
  return { s: a.stripped, t: b.stripped, text, first: placed[1], tAt: placed[6], second: placed[9] };
}

const listed = async (page: Page, text: string) => (await readHighlights(page, text)).map((h) => `${h.word}@${h.start}`);

test('ROW-024-ignore-clears-only-that-occurrence-lowers-the-count-and-the-word-returns-on-the-next-check', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const o = offer(rng);
  const all = [`${o.s}@${o.first.start}`, `${o.t}@${o.tAt.start}`, `${o.s}@${o.second.start}`];

  await openChecker(page);
  await enterOffer(page, o.text);
  expect((await pressCheck(page)).status, 'ROW-024: the page\'s check is answered').toBe(200);
  await expect.poll(() => listed(page, o.text), { message: `ROW-024: before Ignore both "${o.s}" and "${o.t}" are highlighted (seed ${rng.seed})`, timeout: WAIT_MS }).toEqual(all);
  const before = await readCount(page);
  expect(before.n, `ROW-024: the count line gives a number — "${before.text}"`).not.toBeNull();

  await openMenuByPointer(page, o.text, o.first.start, 'ROW-024');
  await chooseIgnore(page, 'ROW-024');
  await expect
    .poll(() => listed(page, o.text), { message: `ROW-024: Ignore clears only the first "${o.s}"; the second "${o.s}" and "${o.t}" stay highlighted (seed ${rng.seed})`, timeout: WAIT_MS })
    .toEqual([all[1], all[2]]);
  expect(await readOfferText(page), 'ROW-024: Ignore leaves the text exactly as entered').toBe(o.text);
  await expect.poll(async () => (await readCount(page)).n, { message: `ROW-024: the count drops by exactly one, from ${before.n}`, timeout: WAIT_MS }).toBe((before.n ?? NaN) - 1);

  expect((await pressCheck(page)).status, 'ROW-024: the second check is answered').toBe(200);
  await expect
    .poll(() => listed(page, o.text), { message: `ROW-024: on the next check the ignored "${o.s}" is flagged again, with the others (seed ${rng.seed})`, timeout: WAIT_MS })
    .toEqual(all);
});

test('ROW-024-control-both-occurrences-are-highlighted-and-the-menu-offers-ignore', async ({ page }) => {
  asActor('anonymous');
  const rng = freshRandom();
  const o = offer(rng);
  await openChecker(page);
  await enterOffer(page, o.text);
  expect((await pressCheck(page)).status, 'ROW-024 control: the page\'s check is answered').toBe(200);
  await expect
    .poll(() => listed(page, o.text), { message: `ROW-024 control: both occurrences of "${o.s}" and "${o.t}" are highlighted (seed ${rng.seed})`, timeout: WAIT_MS })
    .toEqual([`${o.s}@${o.first.start}`, `${o.t}@${o.tAt.start}`, `${o.s}@${o.second.start}`]);
  await openMenuByPointer(page, o.text, o.first.start, 'ROW-024 control');
  await expect(page.locator('[data-element="menu"] [data-element="ignore"]').filter({ visible: true }).first(), 'ROW-024 control: the menu shows Ignore').toBeVisible();
});
